const hadiths = $node["Get Hadith Batch"].json.data.hadiths;
const randomHadith = hadiths[Math.floor(Math.random() * hadiths.length)];

const duas = [
  {
    "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ",
    "translation": "O Allah, I seek refuge in You from anxiety and sorrow.",
    "source": "Sahih Bukhari 7/158"
  },
  {
    "arabic": "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ",
    "translation": "My Lord, forgive me and accept my repentance, for You are the Receiver of Repentance, the Merciful.",
    "source": "Abu Dawud, At-Tirmidhi"
  }
];
const randomDua = duas[Math.floor(Math.random() * duas.length)];

return { 
  hadith_text: randomHadith.contents,
  hadith_number: randomHadith.number,
  hadith_source: "Sahih Bukhari",
  dua_arabic: randomDua.arabic,
  dua_translation: randomDua.translation,
  dua_source: randomDua.source
};

const pTimes = $node["Get Prayer Times"].json.data.timings;
const location = $node["Get Prayer Times"].json.data.meta.city;
const ayah = $node["Get Ayah of the Day"].json.data[0];
const ayahEn = $node["Get Ayah of the Day"].json.data[1];
const content = $node["Select Daily Content"].json;

const html = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DeenFlow — Daily Salafi Muslim Life Assistant</title>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg: #0A0A0A;
            --card-bg: #141414;
            --primary: #4CAF50;
            --text-main: #E0E0E0;
            --text-dim: #888888;
            --accent: #D4AF37;
            --card-border: #222;
        }
        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background-color: var(--bg);
            color: var(--text-main);
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
            line-height: 1.6;
        }
        .container {
            max-width: 480px;
            width: 100%;
        }
        header {
            text-align: center;
            margin-bottom: 40px;
            padding-top: 20px;
        }
        header h1 {
            font-size: 28px;
            font-weight: 300;
            letter-spacing: 4px;
            color: var(--accent);
            margin: 0;
            text-transform: uppercase;
        }
        .card {
            background-color: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 20px;
            padding: 24px;
            margin-bottom: 24px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }
        .card-title {
            font-size: 11px;
            color: var(--text-dim);
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 20px;
            display: block;
            font-weight: 600;
        }
        .prayer-grid {
            display: flex;
            justify-content: space-between;
            gap: 8px;
        }
        .prayer-time {
            text-align: center;
            flex: 1;
        }
        .prayer-name {
            font-size: 10px;
            color: var(--text-dim);
            margin-bottom: 4px;
        }
        .prayer-val {
            font-size: 14px;
            font-weight: 600;
            color: var(--accent);
        }
        .quran-arabic {
            font-family: serif;
            font-size: 24px;
            text-align: right;
            margin-bottom: 16px;
            color: var(--text-main);
        }
        .quran-trans {
            font-size: 14px;
            color: var(--text-dim);
            font-style: italic;
        }
        .hadith-content {
            font-size: 14px;
            color: var(--text-main);
        }
        .source {
            font-size: 10px;
            color: var(--primary);
            margin-top: 12px;
            display: block;
            font-weight: 600;
        }
        .reminder-text {
            font-size: 20px;
            text-align: center;
            color: var(--accent);
            font-style: italic;
            font-weight: 300;
        }
        footer {
            text-align: center;
            font-size: 10px;
            color: var(--text-dim);
            margin-top: 50px;
            letter-spacing: 1px;
            opacity: 0.6;
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>DeenFlow</h1>
            <p style="font-size: 12px; color: var(--text-dim); margin-top: 8px;">Daily Assistant &bull; ${location}</p>
        </header>

        <div class="card">
            <span class="card-title">Prayer Times</span>
            <div class="prayer-grid">
                <div class="prayer-time"> <div class="prayer-name">Fajr</div> <div class="prayer-val">${pTimes.Fajr}</div> </div>
                <div class="prayer-time"> <div class="prayer-name">Dhuhr</div> <div class="prayer-val">${pTimes.Dhuhr}</div> </div>
                <div class="prayer-time"> <div class="prayer-name">Asr</div> <div class="prayer-val">${pTimes.Asr}</div> </div>
                <div class="prayer-time"> <div class="prayer-name">Maghrib</div> <div class="prayer-val">${pTimes.Maghrib}</div> </div>
                <div class="prayer-time"> <div class="prayer-name">Isha</div> <div class="prayer-val">${pTimes.Isha}</div> </div>
            </div>
        </div>

        <div class="card">
            <span class="card-title">Ayah of the Day</span>
            <div class="quran-arabic">${ayah.text}</div>
            <div class="quran-trans">${ayahEn.text}</div>
            <span class="source">QUR'AN ${ayah.surah.number}:${ayah.numberInSurah}</span>
        </div>

        <div class="card">
            <span class="card-title">Hadith of the Day</span>
            <div class="hadith-content">${content.hadith_text}</div>
            <span class="source">${content.hadith_source.toUpperCase()} &bull; #${content.hadith_number}</span>
        </div>

        <div class="card">
            <span class="card-title">Dua of the Day</span>
            <div class="quran-arabic" style="font-size: 20px;">${content.dua_arabic}</div>
            <div class="hadith-content">${content.dua_translation}</div>
            <span class="source">${content.dua_source.toUpperCase()}</span>
        </div>

        <div class="card" style="background: transparent; border: none; box-shadow: none;">
            <div class="reminder-text">
                "And whoever relies upon Allah &mdash; then He is sufficient for him."
            </div>
        </div>

        <footer>
            AUTHENTIC SALAFI LIFE COMPANION &bull; 2025
        </footer>
    </div>
</body>
</html>
`;

return { html };
